BEGIN; CREATE TYPE foo AS (a INT, b INT); ALTER TYPE foo RENAME TO TEXT; CREATE TABLE t (id int, data TEXT); CREATE FUNCTION trigfunc() RETURNS trigger AS $$ BEGIN PERFORM NEW::text; EXECUTE format('ALTER TRIGGER %I ON %I RENAME TO trg2', TG_NAME, TG_TABLE_NAME); RETURN NEW; END; $$ LANGUAGE plpgsql; CREATE TRIGGER trg BEFORE INSERT ON t FOR EACH ROW EXECUTE FUNCTION trigfunc(); INSERT INTO t VALUES (2, ROW(2, power(2, 30))::TEXT); COMMIT;
